import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.Bb5YUzRP.js";import{$ as i,J as a,Q as o,X as s,Y as c,Z as l,et as u,it as d,nt as f,q as p,rt as m,tt as h}from"./chunks/assets.8isJ-IUK.js";var g=JSON.parse(`{"title":"Intervals","description":"","frontmatter":{},"headers":[],"relativePath":"intervals.md","filePath":"intervals.md"}`),_={name:`intervals.md`},v=d+` 1x, `+m+` 2x`,y=f+` 1x, `+h+` 2x`,b=u+` 1x, `+i+` 2x`,x=o+` 1x, `+l+` 2x`,S=s+` 1x, `+c+` 2x`,C=a+` 1x, `+p+` 2x`;function w(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="intervals" tabindex="-1">Intervals <a class="header-anchor" href="#intervals" aria-label="Permalink to “Intervals”">​</a></h1><p>Using the intervals, you can easily vary the value of a field based on other fields.</p><p><img src="/webp/interval.png-90-1788222277562.webp" srcset="`+v+`" alt="Interval" title="" width="904" height="746" loading="lazy" style="width:452px;"></p><p>In this case, the price_m2 is reduced based on the area. This allows you to configure a regressive pricing easily.</p><p>Here&#39;s how the condition modal looks like:</p><p><img src="/webp/interval-condition.png-90-1788222277561.webp" srcset="`+y+`" alt="Interval condition" title="" width="1152" height="856" loading="lazy" style="width:576px;"></p><p>You can click the <code>Infinity</code> button if you want the condition range to be open-ended.</p><h2 id="using-discrete-values-instead-of-a-range" tabindex="-1">Using discrete values instead of a range <a class="header-anchor" href="#using-discrete-values-instead-of-a-range" aria-label="Permalink to “Using discrete values instead of a range”">​</a></h2><p>In addition to ranges, you can also use discrete values to create a simple price table for example.</p><p>The values can either be numbers or strings.</p><h3 id="example-varying-the-price-based-on-the-selected-material" tabindex="-1">Example: varying the price based on the selected material <a class="header-anchor" href="#example-varying-the-price-based-on-the-selected-material" aria-label="Permalink to “Example: varying the price based on the selected material”">​</a></h3><p>Here&#39;s how the <code>material</code> dropdown options look like:</p><p><img src="/webp/material-options.png-90-1788222277563.webp" srcset="`+b+`" alt="Material options" title="" width="1074" height="754" loading="lazy" style="width:537px;"></p><p>Notice that the values are strings. This makes it easier to reference the values in the interval conditions.</p><p>Here&#39;s how to add an interval condition using discrete values:</p><p><img src="/webp/interval-values.png-90-1788222277562.webp" srcset="`+x+`" alt="Interval values" title="" width="1152" height="704" loading="lazy" style="width:576px;"></p><p>The configured interval will look like this</p><p><img src="/webp/material-values.png-90-1788222277563.webp" srcset="`+S+`" alt="Material values" title="" width="908" height="546" loading="lazy" style="width:454px;"></p><p>While you can put these prices in the <a href="/fields.html#field-options">option values</a> directly, this method allows you to configure any number of fields based on the selected material, so it&#39;s more flexible and powerful.</p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>You can also use multiple values in the condition by separating them with a comma. For example, <code>wood,metal</code> will match both values.</p></div><h2 id="using-formulas-in-the-intervals-table" tabindex="-1">Using formulas in the intervals table <a class="header-anchor" href="#using-formulas-in-the-intervals-table" aria-label="Permalink to “Using formulas in the intervals table”">​</a></h2><p>You can also use formulas in the intervals table. This allows you to create more complex calculation.</p><p>Example: Reducing a price based on the quantity</p><div class="tip custom-block"><p class="custom-block-title">The quantity field</p><p>You can create a field called <code>quantity</code> and set the type to <code>Dynamic Variable</code>. This field will be synchronized with the PrestaShop quantity field both ways.</p></div><p><img src="/webp/interval-formulas.png-90-1788222277562.webp" srcset="`+C+`" alt="Interval formulas" title="" width="908" height="618" loading="lazy" style="width:454px;"></p>`,25)]])}var T=e(_,[[`render`,w]]);export{g as __pageData,T as default};